        public static bool ReadHoldsEmptyUnion(ReadStream stream, ref HoldsEmptyUnion value)
        {
            if (!stream.SerializeBits(ref value.Lead, 5))
            {
                return false;
            }
            if (!ReadEmptyUnion(stream, ref value.U))
            {
                return false;
            }
            if (!stream.SerializeBits(ref value.Tail, 7))
            {
                return false;
            }
            return true;
        }

        // StrsMaxBits is the longest wire path; align pads at worst case (SPEC §6.1);
        // StrsMaxBytes rounds it up to the 8-byte write-buffer granularity.
        public const int StrsMaxBits = 158;
        public const int StrsMaxBytes = 24;

        // ZeroStrs: the §5 zero form — all-zero storage, which is default.
        public static void ZeroStrs(ref Strs value)
        {
            value = default;
        }

        public static bool WriteStrs(WriteStream stream, ref Strs value)
        {
            if (!stream.SerializeBits(ref value.Lead, 5))
            {
                return false;
            }
            Debug.Assert(value.SLength >= 0 && value.SLength <= 8, "value.SLength out of range [0, 8]");
            {
                uint offsetValue = (uint)value.SLength;
                if (!stream.SerializeBits(ref offsetValue, 4))
                {
                    return false;
                }
            }
            if (!stream.SerializeBytes(value.S.AsSpan().Slice(0, value.SLength)))
            {
                return false;
            }
            Debug.Assert(value.BLength >= 0 && value.BLength <= 8, "value.BLength out of range [0, 8]");
            {
                uint offsetValue = (uint)value.BLength;
                if (!stream.SerializeBits(ref offsetValue, 4))
                {
                    return false;
                }
            }
            if (!stream.SerializeBytes(value.B.AsSpan().Slice(0, value.BLength)))
            {
                return false;
            }
            if (!stream.SerializeBits(ref value.Tail, 3))
            {
                return false;
            }
            return true;
        }

        public static bool ReadStrs(ReadStream stream, ref Strs value)
        {
            if (!stream.SerializeBits(ref value.Lead, 5))
            {
                return false;
            }
            if (!stream.SerializeInt(ref value.SLength, 0, 8)) // the length guards the slice (§6.3)
            {
                return false;
            }
            {
                Span<byte> bytes = value.S.AsSpan().Slice(0, value.SLength);
                if (!stream.SerializeBytes(bytes))
                {
                    return false;
                }
                if (!ValidUtf8Text(bytes)) // malformed UTF-8 or an interior null is refused (SPEC §4.7)
                {
                    return false;
                }
            }
            if (!stream.SerializeInt(ref value.BLength, 0, 8)) // the length guards the slice (§6.3)
            {
                return false;
            }
            {
                Span<byte> bytes = value.B.AsSpan().Slice(0, value.BLength);
                if (!stream.SerializeBytes(bytes))
                {
                    return false;
                }
            }
            if (!stream.SerializeBits(ref value.Tail, 3))
            {
                return false;
            }
            return true;
        }

        // ArrNestedMaxBits is the longest wire path; align pads at worst case (SPEC §6.1);
        // ArrNestedMaxBytes rounds it up to the 8-byte write-buffer granularity.
        public const int ArrNestedMaxBits = 55;
        public const int ArrNestedMaxBytes = 8;

        // ZeroArrNested: the §5 zero form — all-zero storage, which is default.
        public static void ZeroArrNested(ref ArrNested value)
        {
            value = default;
        }

        public static bool WriteArrNested(WriteStream stream, ref ArrNested value)
        {
            if (!stream.SerializeBits(ref value.Lead, 5))
            {
                return false;
            }
            Debug.Assert(value.ItemsCount >= 0 && value.ItemsCount <= 4, "value.ItemsCount out of range [0, 4]");
            {
                uint offsetValue = (uint)value.ItemsCount;
                if (!stream.SerializeBits(ref offsetValue, 3))
                {
                    return false;
                }
            }
            {
                Span<Eleven> itemsSpan = value.Items.AsSpan();
                for (int i = 0; i < value.ItemsCount; i++)
                {
                    if (!WriteEleven(stream, ref itemsSpan[i]))
                    {
                        return false;
                    }
                }
            }
            if (!stream.SerializeBits(ref value.Tail, 3))
            {
                return false;
            }
            return true;
        }

        public static bool ReadArrNested(ReadStream stream, ref ArrNested value)
        {
            if (!stream.SerializeBits(ref value.Lead, 5))
            {
                return false;
            }
            if (!stream.SerializeInt(ref value.ItemsCount, 0, 4)) // the count guards the loop (§6.3)
            {
                return false;
            }
            {
                Span<Eleven> itemsSpan = value.Items.AsSpan();
                for (int i = 0; i < value.ItemsCount; i++)
                {
                    if (!ReadEleven(stream, ref itemsSpan[i]))
                    {
                        return false;
                    }
                }
            }
            if (!stream.SerializeBits(ref value.Tail, 3))
            {
                return false;
            }
            return true;
        }

        // SoleMaxBits is the longest wire path; align pads at worst case (SPEC §6.1);
        // SoleMaxBytes rounds it up to the 8-byte write-buffer granularity.
        public const int SoleMaxBits = 13;
        public const int SoleMaxBytes = 8;

        // ZeroSole: the §5 zero form — all-zero storage, which is default.
        public static void ZeroSole(ref Sole value)
        {
            value = default;
        }

        public static bool WriteSole(WriteStream stream, ref Sole value)
        {
            if (!stream.SerializeBits(ref value.Only, 13))
            {
                return false;
            }
            return true;
        }

        public static bool ReadSole(ReadStream stream, ref Sole value)
        {
            if (!stream.SerializeBits(ref value.Only, 13))
            {
                return false;
            }
            return true;
        }
    }
}
